import json
import time
from .base import EMSSInterface


class ProxyManager(EMSSInterface):
    """
    EMSsim keywords related to FBOX Proxy
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'  # 'TEST CASE' 'GLOBAL'

    def __init__(self):
        super(ProxyManager, self).__init__()

    def emss_proxy_transparent_mode_on(self, enb_id=None, bts_id=None, alias=None):
        """
        Activates Proxy transparent mode

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.run_emssim_command("proxy_transparent_mode", "on", bts_id=bts_id, alias=alias)

    def emss_proxy_transparent_mode_off(self, enb_id=None, bts_id=None, alias=None):
        """
        Deactivates Proxy transparent mode

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.run_emssim_command("proxy_transparent_mode", "off", bts_id=bts_id, alias=alias)

    def emss_proxy_send_message(self, message, clear=True, enb_id=None, bts_id=None, alias=None):
        """
        Sends message to BTS in proxy transparent mode

        :param message: Message to send in the current Proxy plugin coding format
        :param clear: Clear old messages buffer before send (default=True)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------------+-------------------------------------------------------------------------------------+
        | Examples                 |                                                                                     |
        +==========================+=====================================================================================+
        | emss_proxy_send_message  | ["versionrequest",["generalheader",1528210720040,["acknowledgeinfo",1,"ACK","",0]]] |
        +--------------------------+-------------------------------------------------------------------------------------+
        """
        clear = self._opt_bool(clear)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if isinstance(message, list) or isinstance(message, dict):
            message = json.dumps(message, separators=(',', ':'))

        if clear:
            self.run_emssim_command("proxy_clear", bts_id=bts_id, alias=alias)

        self.run_emssim_command("proxy_send", message, timeout=180, bts_id=bts_id, alias=alias)

    def emss_proxy_get_message(self, timeout=30, interval=2, clear=True, output_string=False, enb_id=None, bts_id=None, alias=None):
        """
        Gets message from BTS in proxy transparent mode

        :param timeout: Maximum time to wait for a message (default=30)
        :param interval: Time between checks for messages (default=2)
        :param clear: Clear message buffer after get (default=True)
        :param output_string: Output message as string instead of complex structures (default=False)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        timeout = self._opt_int(timeout)
        interval = self._opt_int(interval)
        clear = self._opt_bool(clear)
        output_string = self._opt_bool(output_string)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        ret_msg = None

        while timeout > 0:
            ret = self.run_emssim_command("proxy_show", timeout=180, get_full_data=True, bts_id=bts_id, alias=alias)
            for entry in ret:
                if 'msg' in entry:
                    ret_msg = entry['msg']
            if ret_msg is not None:
                break
            time.sleep(interval)
            timeout -= interval

        if clear:
            self.run_emssim_command("proxy_clear", bts_id=bts_id, alias=alias)

        if output_string:
            return ret_msg

        data = None
        if ret_msg is not None:
            data = json.loads(ret_msg)
        return data

    def emss_proxy_clear_message_buffer(self, enb_id=None, bts_id=None, alias=None):
        """
        Clears message buffer

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.run_emssim_command("proxy_clear", bts_id=bts_id, alias=alias)

    def emss_proxy_get_events(self, timeout=180, interval=5, clear=True, enb_id=None, bts_id=None, alias=None):
        """
        Get events received from BTS

        :param timeout: Maximum time to wait for events (default=180)
        :param interval: Time between checks for messages (default=5)
        :param clear: Clear events buffer after get (default=True)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        timeout = self._opt_int(timeout)
        interval = self._opt_int(interval)
        clear = self._opt_bool(clear)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        ret_msg = []

        while timeout > 0:
            ret = self.run_emssim_command("proxy_show", timeout=180, get_full_data=True, bts_id=bts_id, alias=alias)
            for entry in ret:
                if 'msg' in entry:
                    ret_msg.append(entry['msg'])
            if ret_msg:
                break
            time.sleep(interval)
            timeout -= interval

        if clear:
            self.run_emssim_command("proxy_clear", bts_id=bts_id, alias=alias)

        return ret_msg

    def emss_proxy_clear_events(self, enb_id=None, bts_id=None, alias=None):
        """
        Clear events buffer

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.run_emssim_command("proxy_clear", bts_id=bts_id, alias=alias)

    def emss_proxy_format_events(self, events_format='short', enb_id=None, bts_id=None, alias=None):
        """
        Set events format

        :param events_format: short (default), full or hex
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.run_emssim_command("proxy_events_format", events_format, bts_id=bts_id, alias=alias)

    def emss_proxy_ssl_cert(self, cert=None, key=None, cacert=None, enb_id=None, bts_id=None, alias=None):
        """
        Set TLS certificates and private key files

        :param cert: Path to a file containing the user's certificate in PEM format
        :param key: Path to a file containing the user's private PEM-encoded key
        :param cacert: (optional) Path to a file containing PEM-encoded CA certificates
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +---------------------+--------------------------------------------------------------------------+
        | Examples            |                                                                          |
        +=====================+==========================================================================+
        | emss_proxy_ssl_cert | cert=/path/to/cert.pem  key=/path/to/key.pem  cacert=/path/to/cacert.pem |
        +---------------------+--------------------------------------------------------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._assert(cert and key, "Missing cert and/or key option")
        opts = ["-cert %s" % cert, "-key %s" % key]
        if cacert:
            opts.append("-cacert %s" % cacert)

        self.run_emssim_command("proxy_ssl_cert", opts, bts_id=bts_id, alias=alias)

    def emss_proxy_ssl_depth(self, depth=10, enb_id=None, bts_id=None, alias=None):
        """
        Set fbox maximum number of non-self-issued intermediate certificates that can follow the peer certificate
        in a valid certification path. If depth is 0 the PEER must be signed by the trusted ROOT-CA directly;
        if 1 the path can be PEER, CA, ROOT-CA; if 2 the path can be PEER, CA, CA, ROOT-CA, and so on.
        The default value is 10 (the same as apache2 default).

        :param depth: integer
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------------+---------+
        | Examples                 |         |
        +==========================+=========+
        | emss_proxy_ssl_depth     | depth=2 |
        +--------------------------+---------+
        """
        depth = self._opt_int(depth)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.run_emssim_command("proxy_ssl_depth %d" % depth, bts_id=bts_id, alias=alias)

    def emss_proxy_ssl_verify_peer(self, enb_id=None, bts_id=None, alias=None):
        """
        Enable eNodeB SSL certificates verification in fbox

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.run_emssim_command("proxy_ssl_verify peer", bts_id=bts_id, alias=alias)

    def emss_proxy_ssl_verify_none(self, enb_id=None, bts_id=None, alias=None):
        """
        Disable eNodeB SSL certificates verification in fbox

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.run_emssim_command("proxy_ssl_verify none", bts_id=bts_id, alias=alias)

    def emss_proxy_ssl_versions(self, versions, enb_id=None, bts_id=None, alias=None):
        """
        Set fbox supported TLS protocol versions

        :param versions: string: Comma separated TLS versions or 'clear' for default behaviour
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------------+-----------------------------+
        | Examples                 |                             |
        +==========================+=============================+
        | emss_proxy_ssl_depth     | tlsv1.2,tlsv1.1,tlsv1,sslv3 |
        +--------------------------+-----------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.run_emssim_command("proxy_ssl_versions", versions, bts_id=bts_id, alias=alias)
